{
  "claim": "When the latest published median predates the forecast origin and the series is outside the 14-day inactivity gate, short-horizon intervals underestimate uncertainty accumulated since the last observation.",
  "mechanism": "Provider repricing and offer entry or exit can occur during gaps in collection, so the next published median can incorporate changes from both the unobserved days and the forecast horizon. Widening intervals around the existing centre should accommodate those accumulated changes without assuming their direction.",
  "spec": {
    "when": {
      "all": [
        {"fact": "stale", "op": ">=", "value": 1},
        {"fact": "horizon", "op": "<=", "value": 3},
        {"fact": "gate14", "op": "==", "value": false}
      ]
    },
    "do": {
      "action": "scale_width",
      "lo": 1.5,
      "hi": 1.5
    }
  },
  "falsification": "Reject if pooled skill fails to rise overall or in either selection half, headline skill falls, fewer than 200 cells across five series change, or fewer than 90% of the 2000 ISO-week block bootstrap resamples show improvement.",
  "prior_ids_used": ["H11", "H14"],
  "expects": "A modest skill gain if observation gaps conceal additional median transitions, with benefits concentrated at one day. The supplied breakdowns do not establish this slice's coverage, size, or loss, so neither sufficient support nor passage of the fixed test is established."
}
